def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # Locate the three-cell exemplar, in either orientation, away from the background.
    motif = None
    for r in range(h):
        for c in range(w):
            for dr, dc in ((0, 1), (1, 0)):
                cells = [(r + i*dr, c + i*dc) for i in range(3)]
                if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != bg for rr, cc in cells):
                    vals = [grid[rr][cc] for rr, cc in cells]
                    if len(set(vals)) > 1:
                        motif = (cells, vals, dr, dc)
                        break
            if motif: break
        if motif: break
    if not motif:
        return [row[:] for row in grid]
    cells, vals, dr, dc = motif
    motifset = set(cells)
    counts = {}
    for r in range(h):
        for c in range(w):
            if (r, c) not in motifset and grid[r][c] != bg:
                counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    marker = max(counts, key=counts.get)
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == marker:
                for i, val in enumerate(vals):
                    rr, cc = r + (i-1)*dr, c + (i-1)*dc
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = val
    return out
